/**
 * Credentials for the tests, builders of valid request bodies, and helpers that create items through the API.
 */

import type { Express } from 'express'
import jwt from 'jsonwebtoken'
import request from 'supertest'
import { expect } from 'vitest'

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export type Body = Record<string, any>
export type Headers = Record<string, string>

export const TEST_JWT_SECRET = 'test-secret-with-at-least-32-bytes!'

/** A token signed with the test secret, valid for one hour. */
export function token(roles: string[]): string {
  return jwt.sign({ sub: 'tests', roles }, TEST_JWT_SECRET, { algorithm: 'HS256', expiresIn: '1h' })
}

/** Headers of a client allowed to call every endpoint. */
export const headers: Headers = { Authorization: `Bearer ${token(['admin', 'reader'])}` }

/** Headers of a client with a valid token but no role. */
export const headersWithoutRoles: Headers = { Authorization: `Bearer ${token([])}` }

/** A valid body to create an author, with the items it refers to created first. */
export async function authorPayload(app: Express, headers: Headers, variant = 0): Promise<Body> {
  const body: Body = variant === 0 ? { name: 'name 1', email: 'user1@example.com', born: '2024-01-15' } : { name: 'name 2', email: 'user2@example.com', born: '2024-01-16' }
  return body
}

/** Creates an author and returns it as the API answers. */
export async function createAuthor(app: Express, headers: Headers, variant = 0): Promise<Body> {
  const response = await request(app).post('/authors').set(headers).send(await authorPayload(app, headers, variant))
  expect(response.status, response.text).toBe(201)
  return response.body
}

/** A valid body to create a book, with the items it refers to created first. */
export async function bookPayload(app: Express, headers: Headers, variant = 0): Promise<Body> {
  const body: Body = variant === 0 ? { title: 'title 1', isbn: '0000000000000', authorId: null, genre: 'novel', pages: 1, published: '2024-01-15', available: true } : { title: 'title 2', isbn: '0000000000000', authorId: null, genre: 'essay', pages: 2, published: '2024-01-16', available: false }
  body['authorId'] = (await createAuthor(app, headers))['id']
  return body
}

/** Creates a book and returns it as the API answers. */
export async function createBook(app: Express, headers: Headers, variant = 0): Promise<Body> {
  const response = await request(app).post('/books').set(headers).send(await bookPayload(app, headers, variant))
  expect(response.status, response.text).toBe(201)
  return response.body
}

